-- ShopeeFood-like Food Delivery Network mock data (SQL Server)
SET NOCOUNT ON;
GO


IF OBJECT_ID('dbo.driver_positions', 'U') IS NOT NULL DROP TABLE dbo.driver_positions;

IF OBJECT_ID('dbo.order_status_events', 'U') IS NOT NULL DROP TABLE dbo.order_status_events;

IF OBJECT_ID('dbo.order_item_options', 'U') IS NOT NULL DROP TABLE dbo.order_item_options;

IF OBJECT_ID('dbo.order_items', 'U') IS NOT NULL DROP TABLE dbo.order_items;

IF OBJECT_ID('dbo.orders', 'U') IS NOT NULL DROP TABLE dbo.orders;

IF OBJECT_ID('dbo.menu_items', 'U') IS NOT NULL DROP TABLE dbo.menu_items;

IF OBJECT_ID('dbo.option_choices', 'U') IS NOT NULL DROP TABLE dbo.option_choices;

IF OBJECT_ID('dbo.option_groups', 'U') IS NOT NULL DROP TABLE dbo.option_groups;

IF OBJECT_ID('dbo.drivers', 'U') IS NOT NULL DROP TABLE dbo.drivers;

IF OBJECT_ID('dbo.restaurants', 'U') IS NOT NULL DROP TABLE dbo.restaurants;

IF OBJECT_ID('dbo.customers', 'U') IS NOT NULL DROP TABLE dbo.customers;

IF OBJECT_ID('dbo.locations', 'U') IS NOT NULL DROP TABLE dbo.locations;
GO

CREATE TABLE dbo.locations (
  location_id INT PRIMARY KEY,
  lat DECIMAL(9,6) NOT NULL,
  lng DECIMAL(9,6) NOT NULL,
  address NVARCHAR(255) NOT NULL
);

CREATE TABLE dbo.customers (
  customer_id INT PRIMARY KEY,
  full_name NVARCHAR(100) NOT NULL,
  phone VARCHAR(15) NOT NULL,
  email VARCHAR(120) NOT NULL,
  location_id INT NOT NULL,
  created_at DATETIME2(0) NOT NULL
);

CREATE TABLE dbo.restaurants (
  restaurant_id INT PRIMARY KEY,
  restaurant_name NVARCHAR(120) NOT NULL,
  cuisine VARCHAR(50) NOT NULL,
  location_id INT NOT NULL,
  phone VARCHAR(15) NOT NULL,
  rating_avg DECIMAL(3,1) NOT NULL
);

CREATE TABLE dbo.drivers (
  driver_id INT PRIMARY KEY,
  full_name NVARCHAR(100) NOT NULL,
  phone VARCHAR(15) NOT NULL,
  vehicle_type VARCHAR(20) NOT NULL,
  location_id INT NOT NULL,
  rating_avg DECIMAL(3,2) NOT NULL,
  availability VARCHAR(20) NOT NULL
);

CREATE TABLE dbo.option_groups (
  option_group_id INT PRIMARY KEY,
  group_name NVARCHAR(50) NOT NULL,
  select_type VARCHAR(10) NOT NULL
);

CREATE TABLE dbo.option_choices (
  option_choice_id INT PRIMARY KEY,
  option_group_id INT NOT NULL,
  choice_name NVARCHAR(60) NOT NULL,
  extra_price INT NOT NULL
);

CREATE TABLE dbo.menu_items (
  menu_item_id INT PRIMARY KEY,
  restaurant_id INT NOT NULL,
  item_name NVARCHAR(120) NOT NULL,
  base_price INT NOT NULL,
  is_active BIT NOT NULL
);

CREATE TABLE dbo.orders (
  order_id INT PRIMARY KEY,
  customer_id INT NOT NULL,
  restaurant_id INT NOT NULL,
  driver_id INT NOT NULL,
  pickup_location_id INT NOT NULL,
  dropoff_location_id INT NOT NULL,
  driver_to_rest_km DECIMAL(7,3) NOT NULL,
  rest_to_customer_km DECIMAL(7,3) NOT NULL,
  subtotal INT NOT NULL,
  option_surcharge INT NOT NULL,
  delivery_fee INT NOT NULL,
  total_amount INT NOT NULL,
  created_at DATETIME2(0) NOT NULL,
  status_current VARCHAR(20) NOT NULL,
  rating INT NULL
);

CREATE TABLE dbo.order_items (
  order_item_id INT PRIMARY KEY,
  order_id INT NOT NULL,
  menu_item_id INT NOT NULL,
  quantity INT NOT NULL,
  unit_price INT NOT NULL
);

CREATE TABLE dbo.order_item_options (
  order_item_id INT NOT NULL,
  option_group_id INT NOT NULL,
  option_choice_id INT NOT NULL
);

CREATE TABLE dbo.order_status_events (
  event_id INT PRIMARY KEY,
  order_id INT NOT NULL,
  status VARCHAR(20) NOT NULL,
  event_time DATETIME2(0) NOT NULL
);

CREATE TABLE dbo.driver_positions (
  position_id INT PRIMARY KEY,
  driver_id INT NOT NULL,
  order_id INT NOT NULL,
  lat DECIMAL(9,6) NOT NULL,
  lng DECIMAL(9,6) NOT NULL,
  recorded_at DATETIME2(0) NOT NULL
);

-- Optional indexes
CREATE INDEX IX_orders_created_at ON dbo.orders(created_at);
CREATE INDEX IX_order_items_order_id ON dbo.order_items(order_id);
CREATE INDEX IX_status_events_order_id ON dbo.order_status_events(order_id);
CREATE INDEX IX_driver_positions_order_id ON dbo.driver_positions(order_id);
GO

